    case "resubmitTask":
      return addAudit(
        {
          ...state,
          tasks: state.tasks.map((task) =>
            task.id === action.taskId
              ? {
                  ...task,
                  status: "review",
                  version: task.version + 1,
                  rejection: undefined,
                }
              : task,
          ),
        },
        "修改后重新提交审核",
      );
  }
